43	async function getDetailByGlobalId(gid) {
44	  var d = decodeGlobalId(gid)
45	  var ds = null
46	  for (var i = 0; i < DATASETS.length; i++) {
47	    if (DATASETS[i].id === d.dsId) { ds = DATASETS[i]; break }
48	  }
49	  if (!ds) return null
50	  var eng = ensureEngine(ds)
51	  var mapDoc = await eng.getDoc(d.localId)
52	
53	  var meta = await _loadMeta(eng)
54	
55	  // 读 detail 分片找 localId 行
56	  var chunkId = Math.floor(d.localId / meta.detailChunkSize)
57	  var raw = await _readText(eng.basePath + 'detail_' + chunkId + '.txt')
58	
59	  var rows = raw.split('\n')
60	  var line = null
61	  for (var ri = 0; ri < rows.length; ri++) {
62	    var cols = rows[ri].split('|')
63	    if (parseInt(cols[0], 10) === d.localId) { line = cols; break }
64	  }
65	
66	  var details = []
67	  if (line) {
68	    // detail 行：localId|关键词|字段值1|字段值2...（列 2 起按 fields.detail 顺序）
69	    for (var ci = 2; ci < line.length; ci++) {
70	      var rawName = meta.detFieldNames[ci - 2] || ('详情' + (ci - 1))
71	      var name = FIELD_NAME_MAP[rawName] || rawName
72	      // 物化时真实换行编码为字面 \n 两字符（| 是列分隔符，裸换行会断行），这里还原
73	      var value = (line[ci] || '').replace(/\\n/g, '\n')
74	      if (value) details.push({ name: name, value: value })
75	    }
76	  }
77	
78	  return {
79	    isDataset: true,
80	    dsName: ds.name,
81	    title: (mapDoc && mapDoc.title) || '',
82	    // 资料集无年份语义（物化 year=0 → 引擎返回「公元元年」）：年份位显示集标签
83	    yearDisplay: ds.id !== 0 ? ds.tag : ((mapDoc && mapDoc.yearDisplay) || ds.tag),
84	    region: (mapDoc && mapDoc.region) || ds.tag,
85	    keywords: line && line[1] ? line[1].split(',').filter(function(k) { return k }) : [],
86	    details: details
87	  }
88	}
